/**
 * AZMARO seed – idempotent and non-destructive.
 *
 *   npm run db:seed
 *
 * Source of truth: the AZMARO perfume catalogue (94 profiles, db/seed-data/catalogue.ts).
 *  - Re-running updates catalogue copy but NEVER overwrites admin-managed data
 *    (prices, MRP, stock, images, publish/featured flags, settings).
 *  - Prices, MRP and stock are seeded as NULL (unverified) – use the admin API
 *    or `npm run import:pricing` once AZMARO approves them.
 *  - Product photos come from seed-data/product-images.ts (generated by
 *    `npm run import:local-images`). Rows are only added – an existing image row
 *    (status, order, alt text changed by an admin) is never modified.
 *  - An admin user is created only if SEED_ADMIN_EMAIL + SEED_ADMIN_PASSWORD are set.
 */
import "../src/load-env";
import bcrypt from "bcryptjs";
import { ROLE_DEFINITIONS } from "../src/config/roles";
import { env } from "../src/config/env";
import { closeDb, db, ident, insert, insertMany, newId, sql, update, type Sql, type Concentration, type Gender, type NoteBasis, type RoleRow } from "../src/db";
import { settingDefaults } from "../src/modules/settings/settings.service";
import { BRANDS } from "./seed-data/brands";
import { CATALOGUE } from "./seed-data/catalogue";
import { merchandising } from "./seed-data/merchandising";
import { PRODUCT_IMAGES } from "./seed-data/product-images";
import { COLLECTIONS, FAQS, SCENT_FAMILIES } from "./seed-data/scent-families";

const CONCENTRATION: Record<string, Concentration> = { EDP: "EDP", Extrait: "EXTRAIT", EDT: "EDT", Attar: "ATTAR" };
const GENDER: Record<string, Gender> = { men: "MEN", women: "WOMEN", unisex: "UNISEX" };
const NOTE_BASIS: Record<string, NoteBasis> = { published: "PUBLISHED", "editorial-impression": "EDITORIAL_IMPRESSION" };

const count = async (q: Sql) => (await db.one<{ n: number }>(q))!.n;
const idBySlug = async (table: "brands" | "categories" | "products", slug: string) =>
  (await db.one<{ id: string }>(sql`SELECT id FROM ${ident(table)} WHERE slug = ${slug}`))?.id ?? null;

async function seedRoles() {
  for (const r of ROLE_DEFINITIONS) {
    await db.run(sql`
      INSERT INTO roles (name, description, permissions) VALUES (${r.name}, ${r.description}, ${JSON.stringify(r.permissions)}) AS incoming
      ON DUPLICATE KEY UPDATE description = incoming.description, permissions = incoming.permissions`);
  }
}

async function seedBrands() {
  const featured: readonly string[] = merchandising.featuredBrandIds;
  for (const b of BRANDS) {
    const rank = featured.indexOf(b.id);
    const existing = await idBySlug("brands", b.slug);
    if (existing) await update(db, "brands", { name: b.name }, sql`id = ${existing}`);
    else
      await insert(db, "brands", {
        slug: b.slug,
        name: b.name,
        description: b.description,
        imageUrl: b.image,
        isPublished: b.isPublished,
        isFeatured: rank >= 0,
        featuredRank: rank >= 0 ? rank : null,
      });
  }
}

async function seedCategories() {
  for (const [i, f] of SCENT_FAMILIES.entries()) {
    const existing = await idBySlug("categories", f.slug);
    if (existing) await update(db, "categories", { name: f.name, shortName: f.shortName }, sql`id = ${existing}`);
    else await insert(db, "categories", { ...f, type: "SCENT_FAMILY", sortOrder: i });
  }
  for (const [i, c] of COLLECTIONS.entries()) {
    const existing = await idBySlug("categories", c.slug);
    if (existing) await update(db, "categories", { name: c.name }, sql`id = ${existing}`);
    else await insert(db, "categories", { ...c, type: "COLLECTION", sortOrder: i });
  }
}

async function seedProducts() {
  const brands = new Map((await db.many<{ id: string; slug: string }>(sql`SELECT id, slug FROM brands`)).map((b) => [b.slug, b.id]));
  const categories = new Map((await db.many<{ id: string; slug: string }>(sql`SELECT id, slug FROM categories`)).map((c) => [c.slug, c.id]));
  const collectionId = categories.get("middle-eastern")!;
  const featured: readonly string[] = merchandising.featuredSlugs;
  let created = 0;

  for (const [index, e] of CATALOGUE.entries()) {
    const brandId = brands.get(e.brandId);
    if (!brandId) throw new Error(`Unknown brand ${e.brandId} for ${e.slug}`);
    const content = {
      name: e.name,
      catalogueName: e.catalogueName,
      brandId,
      brandLabel: e.brandLabel,
      fragranceFamily: e.fragranceFamily,
      noteBasis: NOTE_BASIS[e.noteBasis]!,
      topNotes: e.topNotes,
      heartNotes: e.heartNotes,
      baseNotes: e.baseNotes,
      scentCharacter: e.scentCharacter,
      description: e.description,
      occasions: e.occasions,
      season: e.season,
      targetAudience: e.targetAudience,
      gender: e.gender ? GENDER[e.gender]! : null,
      concentration: e.concentration ? CONCENTRATION[e.concentration]! : null,
      concentrationNote: e.concentrationNote,
      researchBasis: e.researchBasis,
      reviewNote: e.reviewNote,
      inventorySizeMl: e.inventorySizeMl,
      sortOrder: index,
    };
    const rank = featured.indexOf(e.slug);
    const existing = await idBySlug("products", e.slug);
    let productId: string;
    if (existing) {
      productId = existing;
      await update(db, "products", content, sql`id = ${productId}`);
    } else {
      productId = await insert(db, "products", { slug: e.slug, ...content, isPublished: true, isFeatured: rank >= 0, featuredRank: rank >= 0 ? rank : null });
      created++;
    }

    const categoryIds = [collectionId, ...e.scentFamilies.map((s) => categories.get(s)!)];
    for (const categoryId of categoryIds) {
      await db.run(sql`INSERT IGNORE INTO product_categories (productId, categoryId) VALUES (${productId}, ${categoryId})`);
    }

    // Size from the inventory name; price / MRP / stock stay NULL until verified.
    if (e.inventorySizeMl) {
      const variantId = newId();
      const { affectedRows } = await db.run(
        sql`INSERT IGNORE INTO product_variants (id, productId, sizeMl) VALUES (${variantId}, ${productId}, ${e.inventorySizeMl})`,
      );
      if (affectedRows) await insert(db, "inventory", { variantId });
    }
  }
  return created;
}

async function seedProductImages() {
  const brandNames = new Map(BRANDS.map((b) => [b.id, b.name]));
  const bySlug = new Map(CATALOGUE.map((e) => [e.slug, e]));
  let added = 0;
  for (const img of PRODUCT_IMAGES) {
    const entry = bySlug.get(img.slug);
    const productId = await idBySlug("products", img.slug);
    if (!entry || !productId) throw new Error(`Image manifest references unknown product ${img.slug}`);
    if (await db.one(sql`SELECT id FROM product_images WHERE productId = ${productId} AND url = ${img.url}`)) continue;
    await insert(db, "product_images", {
      productId,
      url: img.url,
      alt: `${brandNames.get(entry.brandId) ?? ""} ${entry.name} bottle`.trim(),
      status: img.status,
      sourceUrl: img.sourceUrl,
      sourcePageUrl: img.sourcePageUrl,
      workbookStatus: img.workbookStatus,
      notes: img.notes,
    });
    added++;
  }
  return added;
}

async function seedFaqsAndSettings() {
  if ((await count(sql`SELECT COUNT(*) AS n FROM faqs`)) === 0) {
    await insertMany(db, "faqs", FAQS.map((f, i) => ({ ...f, sortOrder: i })));
  }
  for (const [key, value] of Object.entries(settingDefaults())) {
    await db.run(sql`INSERT IGNORE INTO settings (\`key\`, value, updatedBy) VALUES (${key}, ${JSON.stringify(value)}, 'seed')`);
  }
}

async function seedAdmin() {
  const email = env.SEED_ADMIN_EMAIL?.toLowerCase();
  const password = env.SEED_ADMIN_PASSWORD;
  if (!email || !password) return "skipped (set SEED_ADMIN_EMAIL and SEED_ADMIN_PASSWORD to create one)";
  if (password.length < 12) throw new Error("SEED_ADMIN_PASSWORD must be at least 12 characters.");
  const role = (await db.one<RoleRow>(sql`SELECT * FROM roles WHERE name = 'ADMIN'`))!;
  const existing = await db.one(sql`SELECT id FROM users WHERE email = ${email}`);
  if (existing) {
    await update(db, "users", { roleId: role.id, isActive: true }, sql`email = ${email}`);
    return `ensured ADMIN role for ${email} (password unchanged)`;
  }
  await insert(db, "users", {
    email,
    name: env.SEED_ADMIN_NAME ?? "AZMARO Admin",
    passwordHash: await bcrypt.hash(password, env.BCRYPT_ROUNDS),
    roleId: role.id,
    emailVerifiedAt: new Date(),
  });
  return `created ${email}`;
}

async function main() {
  await seedRoles();
  await seedBrands();
  await seedCategories();
  const created = await seedProducts();
  const imagesAdded = await seedProductImages();
  await seedFaqsAndSettings();
  const admin = await seedAdmin();
  const [products, variants, priced, approvedImages] = await Promise.all([
    count(sql`SELECT COUNT(*) AS n FROM products`),
    count(sql`SELECT COUNT(*) AS n FROM product_variants`),
    count(sql`SELECT COUNT(*) AS n FROM product_variants WHERE price IS NOT NULL`),
    count(sql`SELECT COUNT(*) AS n FROM product_images WHERE status = 'APPROVED'`),
  ]);
  console.log(`Seed complete: ${products} products (${created} new), ${variants} variants, ${priced} with confirmed prices.`);
  console.log(`Images: ${imagesAdded} added, ${approvedImages} approved for display.`);
  console.log(`Admin user: ${admin}`);
}

main()
  .catch((e) => {
    console.error(e);
    process.exitCode = 1;
  })
  .finally(() => closeDb());
